import functools

_UNHASHABLE = object()


def _make_key(args, kwargs):
    """Build a cache key from arguments.

    Positional and keyword arguments are both part of the key and the
    keyword order does not matter.  Returns None if any argument cannot be
    hashed; such calls are simply not cached.
    """
    key = []
    for value in args:
        if not isinstance(value, (bool, str, int, float, bytes, frozenset)):
            try:
                hash(value)
            except TypeError:
                return None
            key.append(value)
    if kwargs:
        key.append(kwargs.keys())
        for name, value in kwargs.items():
            if not isinstance(value, (bool, str, int, float, bytes, frozenset)):
                try:
                    hash(value)
                except TypeError:
                    return None
            key.append((name, value))
    return tuple(key)


def memoize(fn):
    cache = {}
    stats = {"hits": 0, "misses": 0}

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        key = _make_key(args, kwargs)
        if key is not None and key in cache:
            stats["hits"] += 1
            return cache[key]
        stats["misses"] += 1
        result = fn(*args, **kwargs)
        if key is not None:
            cache[key] = result
        return result

    wrapper.cache_info = lambda: dict(stats, size=len(cache))

    def cache_clear():
        cache.clear()
        stats.update(hits=0, misses=0)

    wrapper.cache_clear = cache_clear
    return wrapper
