{"content":""""A small memoize decorator with hit/miss counters."""
import functools


def _hashable(value):
    try:
        hash(value)
    except TypeError:
        return False
    return True


def _make_key(args, kwargs):
    """Build a cache key from arguments.

    The key covers both positional and keyword arguments; keyword order
    does not matter.  Returns None if any argument value cannot be hashed;
    such calls are simply not cached.
    """
    if any(not _hashable(value) for value in args):
        return None
    if kwargs and any(not _hashable(value) for value in kwargs.values()):
        return None
    key = list(args)
    # Sorting by keyword name makes the key independent of keyword order.
    key.extend(sorted(kwargs.items()))
    return tuple(key)


def memoize(fn):
    cache = {}
    stats = {"hits": 0, "misses": 0}

    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        key = _make_key(args, kwargs)
        if key is not None and key in cache:
            stats["hits"] += 1
            return cache[key]
        stats["misses"] += 1
        result = fn(*args, **kwargs)
        if key is not None:
            cache[key] = result
        return result

    wrapper.cache_info = lambda: dict(stats, size=len(cache))

    def cache_clear():
        cache.clear()
        stats.update(hits=0, misses=0)

    wrapper.cache_clear = cache_clear
    return wrapper
